create or replace function public.admin_conversion_dashboard(range_days integer default 30) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare d integer:=greatest(7,least(coalesce(range_days,30),90)); result jsonb; begin if auth.uid() is null or not private.has_role('admin'::public.user_role) then raise exception 'Admin access required'; end if; with cohort as (select u.id,u.created_at,u.email_confirmed_at,case when u.raw_user_meta_data->>'signup_intent' in ('account','follow','score_report','pickem') then u.raw_user_meta_data->>'signup_intent' else 'unknown' end signup_intent,exists(select 1 from public.pickem_picks p where p.user_id=u.id) has_pick from auth.users u where u.created_at>=now()-make_interval(days=>d)), intents as (select coalesce(jsonb_agg(jsonb_build_object('intent',signup_intent,'accounts',accounts,'confirmed',confirmed,'pickem_participants',participants) order by accounts desc),'[]'::jsonb) value from (select signup_intent,count(*) accounts,count(*) filter(where email_confirmed_at is not null) confirmed,count(*) filter(where has_pick) participants from cohort group by signup_intent) g) select jsonb_build_object('intent_breakdown',intents.value) into result from intents; return result; end; $$;
